def _agent_notebook_id(path):
    "Build a filesystem-safe id for an agent notebook run."
    rel = Path(path).with_suffix("").as_posix()
    rel = re.sub(r"[^A-Za-z0-9_.-]+", "-", rel).strip("-.")
    return rel or "notebook"

